    for (const f of ['buying_tips', 'watch_out']) {
      for (const s of nonEmpty([].concat(pre(id)[f] ?? []).flatMap(sentences), `${id} ${f}`, 2)) {
        if (POINTER.test(s) || ownedElsewhere(s, to)) continue;
        assert.ok(body.includes(s), `${id} ${f} sentence not on ${to}: ${s}`);
      }
